      "applicationNotes": [
        {
          "clauseId": "C_MEM_COAL_2026_16",
          "summary": "国家矿山安全监察局答复：第十六条双回路供电重大隐患仅针对井工煤矿；第21号令于2026年7月1日施行后，矿安〔2023〕125号通知已废止。",
          "sourceUrl": "https://www.chinamine-safety.gov.cn/hd/lyhf/202606/t20260602_606037.shtml",
          "sourceDate": "2026-07-30",
          "evidenceId": "E_MEM_COAL_CLARIFICATION_1_20261001"
        },
        {
          "clauseId": "C_MEM_COAL_2026_13",
          "summary": "国家矿山安全监察局答复：第十三条第（二）项所指电气设备限于纳入煤矿安全标志管理的电气设备。",
          "sourceUrl": "https://www.chinamine-safety.gov.cn/hd/lyhf/202606/t20260612_607556.shtml",
          "sourceDate": "2026-07-30",
          "evidenceId": "E_MEM_COAL_CLARIFICATION_2_20261001"
        },
        {
          "clauseId": "C_MEM_COAL_2026_20",
          "summary": "国家矿山安全监察局答复：第二十条第（十八）项不包括防爆柴油机无轨胶轮车自身装配、用于车辆启动且不具备外部充电条件的车载锂电池；这些限定须同时满足。",
          "sourceUrl": "https://www.chinamine-safety.gov.cn/hd/lyhf/202607/t20260727_678230.shtml",
          "sourceDate": "2026-07-30",
          "evidenceId": "E_MEM_COAL_CLARIFICATION_3_20261001"
        },
        {
          "clauseId": "C_MEM_COAL_2026_20",
          "summary": "国家矿山安全监察局答复：第二十条第（十八）项所称锂电池不包含监控、通信、人员位置监测、视频、应急广播、避险等设备的备用电源。",
          "sourceUrl": "https://www.chinamine-safety.gov.cn/hd/lyhf/202606/t20260606_606637.shtml",
          "sourceDate": "2026-07-30",
          "evidenceId": "E_MEM_COAL_CLARIFICATION_4_20261001"
        },
        {
          "clauseId": "C_MEM_COAL_2026_20",
          "summary": "国家矿山安全监察局答复：第二十条第（十一）项安设位置判定限于机头、机尾两组。风流从机头到机尾时，机头从下风侧最后一个驱动滚筒起算（没有驱动滚筒时从卸载滚筒起算），机尾从改向滚筒起算；反向风流时，机头从卸载滚筒、机尾从改向滚筒起算。对应下风侧10–20m未安设烟雾、一氧化碳传感器的属于该情形；不能仅因中段滚筒或机头、机尾多个滚筒未逐个配置而认定。",
          "sourceUrl": "https://www.chinamine-safety.gov.cn/hd/lyhf/202607/t20260723_677799.shtml",
          "sourceDate": "2026-07-31",
          "evidenceId": "E_MEM_COAL_CLARIFICATION_5_20261001"
        },
        {
          "clauseId": "C_MEM_COAL_2026_20",
          "summary": "国家矿山安全监察局答复：第二十条第（十一）项适用于所有巷道，包括进风巷和回风巷。",
          "sourceUrl": "https://www.chinamine-safety.gov.cn/hd/lyhf/202606/t20260613_607598.shtml",
          "sourceDate": "2026-07-20",
          "evidenceId": "E_MEM_COAL_CLARIFICATION_6_20261001"
        },
        {
          "clauseId": "C_MEM_COAL_2026_3",
          "summary": "国家矿山安全监察局发布说明：本版重大事故隐患采用封闭列举，限于标准列出的情形；执行争议由该局解释。不得把其他一般违规自动扩大为本标准重大事故隐患。",
          "sourceUrl": "https://www.chinamine-safety.gov.cn/xw/mkaqjcxw/202606/t20260604_606401.shtml",
          "sourceDate": "2026-06-04",
          "evidenceId": "E_MEM_COAL_CLARIFICATION_7_20261001"
        }
      ]
